window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2dbe784b7eb59f49"]={"versions": [{"id": "FIG-2dbe784b7eb59f49", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm (SPEM/UML-Aktivitätsorientiert) zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung einer ausführbaren Anwendung (<code>Executable Application</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren maschinenspezifische Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktivitäten (horizontale Prozesspfeile):\n<ul class=\"fig-list\"><li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf der ausführbaren Anwendung.\n</li><li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.\n</li><li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.\n</li></ul>\n</li><li>Arbeits- und Konfigurationsartefakte:\n<ul class=\"fig-list\"><li><code>Executable Application</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Binär-/Software-Artefakt (Kardinalität <code>1</code> als Eingang).\n</li><li><code>Process</code> (Dokument-Symbol): Manifest-Beschreibungsartefakt für den instanziierten Prozess (Kardinalität <code>1..*</code> als Ausgang von <code>Define Process</code>; Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).\n</li><li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration/Plattform-Manifest (Kardinalität <code>1</code> jeweils als Eingang für <code>Define Startup Configuration</code> und <code>Define Execution Dependencies</code>).\n</li><li><code>Mode-dependent ...</code> (Dokument-Symbol am unteren Rand): Modenabhängige Prozesskonfigurationen (Ausgang mit Kardinalität <code>1..*</code> von beiden Folgeaktivitäten).\n</li></ul>\n</li><li>Kontroll- und Datenflüsse:\n<ul class=\"fig-list\"><li>Stereotypisierte gerichtete Kanten («input», «output») mit expliziten Kardinalitäten verbinden Artefakte und Aktivitäten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Workflow beginnt mit der Übergabe einer <code>Executable Application</code> («input», 1) an die Aktivität <code>Define Process</code>.\n</li><li><code>Define Process</code> erzeugt daraus mindestens eine Prozessdefinition <code>Process</code> («output», 1..*).\n</li><li>Die resultierende <code>Process</code>-Spezifikation wird zusammen mit dem <code>Machine Manifest</code> parallel in zwei Folgeaktivitäten eingespeist:\n<ul class=\"fig-list\"><li>Eingang in <code>Define Startup Configuration</code> («input», 1 für <code>Process</code> und 1 für <code>Machine Manifest</code>).\n</li><li>Eingang in <code>Define Execution Dependencies</code> («input», 1 für <code>Process</code> und 1 für <code>Machine Manifest</code>).\n</li></ul>\n</li><li>Beide Aktivitäten generieren modenabhängige Prozess- und Ausführungsbeschreibungen (<code>Mode-dependent ...</code>, «output», jeweils 1..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den Entwicklungsprozess der AUTOSAR Adaptive Platform: Ein Prozess ist eine Instanziierung einer <code>Executable Application</code> auf einer Maschine. Für die vollständige Deployment-Konfiguration muss ein Prozess sowohl über Startkonfigurationen als auch über Ausführungsabhängigkeiten im Kontext des <code>Machine Manifest</code> verfügen. Werkzeuge für den Adaptive-Workflow müssen diese Artefakt-Abhängigkeiten und Kardinalitäten validieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4747b509285e17c5", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm (SPEM/UML-Aktivitätsorientiert) zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung einer ausführbaren Anwendung (<code>Executable Application</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren maschinenspezifische Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktivitäten (horizontale Prozesspfeile):\n<ul class=\"fig-list\"><li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf der ausführbaren Anwendung.\n</li><li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).\n</li><li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.\n</li><li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.\n</li></ul>\n</li><li>Arbeits- und Konfigurationsartefakte:\n<ul class=\"fig-list\"><li><code>Executable Application</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).\n</li><li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).\n</li><li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..*</code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..*</code>; Eingang in Folgeaktivitäten mit <code>1</code>).\n</li><li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).\n</li><li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).\n</li></ul>\n</li><li>Beziehungen &amp; Kanten:\n<ul class=\"fig-list\"><li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.\n</li><li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine <code>Executable Application</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.\n</li><li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..*) fortgeführt, wodurch eine <code>1..*</code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.\n</li><li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:\n<ul class=\"fig-list\"><li><code>Define Startup Configuration</code> übergeben,\n</li><li><code>Define Execution Dependencies</code> übergeben.\n</li></ul>\n</li><li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der Ausführungs- und Startkonfigurationen erfolgt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1e7f6033efbc0fd4", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm (SPEM/UML-Aktivitätsorientiert) zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung einer ausführbaren Anwendung (<code>Executable Application</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren maschinenspezifische Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktivitäten (horizontale Prozesspfeile):\n<ul class=\"fig-list\"><li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf der ausführbaren Anwendung.\n</li><li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).\n</li><li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.\n</li><li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.\n</li></ul>\n</li><li>Arbeits- und Konfigurationsartefakte:\n<ul class=\"fig-list\"><li><code>Executable Application</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).\n</li><li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).\n</li><li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..*</code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..*</code>; Eingang in Folgeaktivitäten mit <code>1</code>).\n</li><li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).\n</li><li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).\n</li></ul>\n</li><li>Beziehungen &amp; Kanten:\n<ul class=\"fig-list\"><li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.\n</li><li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine <code>Executable Application</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.\n</li><li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..*) fortgeführt, wodurch eine <code>1..*</code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.\n</li><li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:\n<ul class=\"fig-list\"><li><code>Define Startup Configuration</code> übergeben,\n</li><li><code>Define Execution Dependencies</code> übergeben.\n</li></ul>\n</li><li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der Ausführungs- und Startkonfigurationen erfolgt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-045cebe68a862c07", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung eines ausführbaren Programms (<code>(Adaptive) Executable</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren Verknüpfung mit dem Entwurf und den maschinenspezifischen Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktivitäten (horizontale Prozesspfeile):\n<ul class=\"fig-list\"><li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf dem Executable.\n</li><li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).\n</li><li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.\n</li><li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.\n</li></ul>\n</li><li>Arbeits- und Konfigurationsartefakte:\n<ul class=\"fig-list\"><li><code>(Adaptive) Executable</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).\n</li><li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).\n</li><li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..*</code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..*</code> und <code>1</code>; Eingang in Folgeaktivitäten mit <code>1</code>).\n</li><li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).\n</li><li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).\n</li></ul>\n</li><li>Beziehungen &amp; Kanten:\n<ul class=\"fig-list\"><li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.\n</li><li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein <code>(Adaptive) Executable</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.\n</li><li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..*) fortgeführt, wodurch eine <code>1..*</code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.\n</li><li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:\n<ul class=\"fig-list\"><li><code>Define Startup Configuration</code> übergeben,\n</li><li><code>Define Execution Dependencies</code> übergeben.\n</li></ul>\n</li><li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> basiert auf einem <code>(Adaptive) Executable</code> und erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der maschinenspezifischen Ausführungs- und Startkonfigurationen erfolgt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b4046f320f337be7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Ablaufdiagramm zur Spezifikation und Konfiguration von Prozessen in der AUTOSAR Adaptive Platform. Das Diagramm modelliert den methodischen Workflow zur Überführung eines ausführbaren Programms (<code>(Adaptive) Executable</code>) in instanziierte Prozesse (<code>Process</code>) sowie deren Verknüpfung mit dem Entwurf und den maschinenspezifischen Start- und Ausführungsabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktivitäten (horizontale Prozesspfeile):\n<ul class=\"fig-list\"><li><code>Define Process</code>: Erzeugt Prozessinstanzen basierend auf dem Executable.\n</li><li><code>Associate Process with ProcessDesign</code>: Verknüpft die Prozessinstanz mit dem zugehörigen Entwurfsmodell (<code>Process Design</code>).\n</li><li><code>Define Startup Configuration</code>: Definiert die zustands- und modenabhängigen Startparameter für den Prozess auf einer konkreten Maschine.\n</li><li><code>Define Execution Dependencies</code>: Definiert modenabhängige Ausführungs- und Startreihenfolgen bzw. Abhängigkeiten zwischen Prozessen auf einer Maschine.\n</li></ul>\n</li><li>Arbeits- und Konfigurationsartefakte:\n<ul class=\"fig-list\"><li><code>(Adaptive) Executable</code> (Briefumschlag-Symbol mit Port-Leiste links): Ausführbares Software-Artefakt (Kardinalität <code>1</code> als Eingang).\n</li><li><code>Process Design</code> (Dokument-Symbol): Entwurfsspezifikation des Prozesses (Kardinalität <code>1..*</code> als Eingang in <code>Associate Process with ProcessDesign</code>; assoziiert mit Kardinalität <code>1</code> zu <code>Process</code>).\n</li><li><code>Process</code> (Dokument-Symbol): Instanziierter Prozess (Ausgang von <code>Define Process</code> mit <code>1..*</code>; Ein- und Ausgang bei <code>Associate Process with ProcessDesign</code> jeweils mit <code>1..*</code> und <code>1</code>; Eingang in Folgeaktivitäten mit <code>1</code>).\n</li><li><code>Machine Manifest</code> (Briefumschlag-Symbol mit Port-Leiste links): Maschinenkonfiguration (Kardinalität <code>1</code> jeweils als Eingang für Folgeaktivitäten).\n</li><li><code>Mode-dependent ...</code> (Dokument-Symbol): Modenabhängige Konfigurationen (Ausgang mit Kardinalität <code>1..*</code>).\n</li></ul>\n</li><li>Beziehungen &amp; Kanten:\n<ul class=\"fig-list\"><li>Stereotypisierte Datenflüsse («input», «output») mit Kardinalitäten.\n</li><li>Gestrichelte Assoziationskante zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein <code>(Adaptive) Executable</code> wird als Eingang («input», 1) an <code>Define Process</code> übergeben, welche ein oder mehrere <code>Process</code>-Artefakte («output», 1..*) generiert.\n</li><li>In der Aktivität <code>Associate Process with ProcessDesign</code> werden ein oder mehrere <code>Process</code>-Artefakte («input», 1..<em>) mit der Entwurfsspezifikation <code>Process Design</code> («input», 1..</em>) zusammengeführt; das aktualisierte Artefakt wird als <code>Process</code> («output», 1..*) fortgeführt, wodurch eine <code>1..*</code> zu <code>1</code>-Zuordnung zwischen <code>Process</code> und <code>Process Design</code> etabliert wird.\n</li><li>Der definierte <code>Process</code> («input», 1) wird zusammen mit dem <code>Machine Manifest</code> («input», 1) parallel an:\n<ul class=\"fig-list\"><li><code>Define Startup Configuration</code> übergeben,\n</li><li><code>Define Execution Dependencies</code> übergeben.\n</li></ul>\n</li><li>Beide Aktivitäten erzeugen modenabhängige Konfigurationselemente (<code>Mode-dependent ...</code>, «output», jeweils 1..*).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für den AUTOSAR Adaptive Workflow: Die Konfiguration eines <code>Process</code> basiert auf einem <code>(Adaptive) Executable</code> und erfordert die formale Verknüpfung mit einem <code>Process Design</code>. Mehrere Prozesse können demselben <code>Process Design</code> zugeordnet sein (<code>1..*</code> zu <code>1</code>). Werkzeugketten müssen sicherstellen, dass die Zuordnung zwischen Design und Instanz vor oder während der Erstellung der maschinenspezifischen Ausführungs- und Startkonfigurationen erfolgt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2dbe784b7eb59f49", "to": "FIG-4747b509285e17c5", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Aktivität <code>Associate Process with ProcessDesign</code> mit Eingängen von <code>Process Design</code> (Kardinalität <code>1..*</code>) und <code>Process</code> (Kardinalität <code>1..*</code>) sowie Ausgang zu <code>Process</code> (Kardinalität <code>1..*</code>).\n</li><li>Ergänzung des Artefakts <code>Process Design</code>.\n</li><li>Ergänzung einer gestrichelten Assoziationslinie zwischen <code>Process</code> (Kardinalität <code>1..*</code>) und <code>Process Design</code> (Kardinalität <code>1</code>).\n</li></ul>"}, {"from": "FIG-4747b509285e17c5", "to": "FIG-1e7f6033efbc0fd4", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umstellung des Layouts von vertikalem zu horizontal-versetztem Fluss: <code>Executable Application</code> befindet sich nun oben links mit horizontalem Pfeil auf <code>Define Process</code>.\n</li><li>Die Beschriftungen <code>Define Process</code> und <code>Process Design</code> sind nun oberhalb der jeweiligen Symbole platziert.\n</li><li>Bei der Assoziationslinie und den Pfeilen zwischen <code>Process</code> und <code>Associate Process with ProcessDesign</code> wurden zusätzliche Kardinalitätsangaben <code>1</code> an den Verbindungspunkten visualisiert.\n</li></ul>"}, {"from": "FIG-1e7f6033efbc0fd4", "to": "FIG-045cebe68a862c07", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umbenennung des Eingangs-Artefakts von <code>Executable Application</code> zu <code>(Adaptive) Executable</code>.\n</li></ul>"}, {"from": "FIG-045cebe68a862c07", "to": "FIG-b4046f320f337be7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
